wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier, state_rw};
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Approved extension: record the input this call received in the shared store.
        state_rw::put("last-input", &feed_url);

        // Read the time once.
        let seconds = wall_clock::now().seconds;

        // The one permitted fetch. A transport failure comes back as a value and
        // counts as zero characters fetched. An off-allowlist URL traps at the
        // boundary, as the capability intends.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!(
            "heartbeat: t={} fetched={} chars from {}",
            seconds, fetched, feed_url
        );

        // The contract requires `notified == true`. Retry a few times. If the
        // channel still refuses, abort rather than emit an output that breaks
        // the contract.
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
